package io.github.miklires.mclans.command;
import io.github.miklires.mclans.MClansPlugin;import io.github.miklires.mclans.api.*;import io.github.miklires.mclans.clan.ClanService;import io.github.miklires.mclans.gui.ClanGui;import io.papermc.paper.command.brigadier.*;import java.util.*;import java.util.concurrent.CompletableFuture;import org.bukkit.Bukkit;import org.bukkit.command.CommandSender;import org.bukkit.entity.Player;import org.jetbrains.annotations.NotNull;
public final class ClanCommand implements BasicCommand{private final MClansPlugin plugin;private final ClanService service;private final ClanGui gui;public ClanCommand(MClansPlugin plugin,ClanService service,ClanGui gui){this.plugin=plugin;this.service=service;this.gui=gui;}@Override public void execute(@NotNull CommandSourceStack source,@NotNull String[] args){CommandSender sender=source.getSender();if(args.length>0&&args[0].equalsIgnoreCase("reload")){if(!sender.hasPermission("mclans.reload")){deny(sender);return;}try{plugin.reloadRuntime();sender.sendMessage(ClanService.color("&aКонфигурация перезагружена."));}catch(RuntimeException e){sender.sendMessage(ClanService.color("&cОшибка: "+e.getMessage()));}return;}if(!(sender instanceof Player player)){sender.sendMessage("Players only");return;}if(!player.hasPermission("mclans.use")){deny(player);return;}if(args.length==0||args[0].equalsIgnoreCase("info")){info(player,args);return;}switch(args[0].toLowerCase(Locale.ROOT)){case"create"->{if(args.length!=3){usage(player);return;}complete(player,service.create(player,args[1],args[2]).thenApply(v->true),"Клан создан.");}case"invite"->{Player target=args.length>1?Bukkit.getPlayerExact(args[1]):null;if(target==null){player.sendMessage(ClanService.color("&cИгрок не найден."));return;}complete(player,service.invite(player,target),"Приглашение отправлено.");}case"accept"->{if(args.length!=2){usage(player);return;}complete(player,service.accept(player,args[1]),"Вы вступили в клан.");}case"leave"->complete(player,service.leave(player),"Вы покинули клан.");case"disband"->{if(args.length!=2||!args[1].equalsIgnoreCase("confirm")){player.sendMessage(ClanService.color("&cПодтвердите: /clan disband confirm"));return;}complete(player,service.disband(player),"Клан распущен.");}case"kick"->{Player target=args.length>1?Bukkit.getPlayerExact(args[1]):null;if(target==null){player.sendMessage(ClanService.color("&cИгрок должен быть онлайн."));return;}complete(player,service.kick(player,target),"Игрок исключён.");}case"promote","demote"->{Player target=args.length>1?Bukkit.getPlayerExact(args[1]):null;if(target==null){player.sendMessage(ClanService.color("&cИгрок должен быть онлайн."));return;}ClanRole role=args[0].equalsIgnoreCase("promote")?ClanRole.OFFICER:ClanRole.MEMBER;complete(player,service.setRole(player,target,role),"Роль изменена.");}case"ff"->{if(args.length!=2){usage(player);return;}complete(player,service.setFriendlyFire(player,args[1].equalsIgnoreCase("on")),"Friendly fire изменён.");}case"bank"->{ClanView clan=service.cached(player.getUniqueId()).orElse(null);player.sendMessage(ClanService.color(clan==null?"&cВы не в клане.":"&eБаланс клана: &f"+clan.bank()));}default->usage(player);}}
 private void info(Player player,String[] args){if(args.length>1){service.repository().findClan(args[1]).whenComplete((found,error)->plugin.scheduler().player(player,()->{if(error!=null||found.isEmpty())player.sendMessage(ClanService.color("&cКлан не найден."));else gui.open(player,found.get());}));return;}ClanView clan=service.cached(player.getUniqueId()).orElse(null);if(clan==null)player.sendMessage(ClanService.color("&eВы не состоите в клане. Создать: /clan create <name> <tag>"));else gui.open(player,clan);}
 private void complete(Player player,CompletableFuture<Boolean> future,String success){future.whenComplete((ok,error)->plugin.scheduler().player(player,()->{if(error!=null)player.sendMessage(ClanService.color("&cОперация не выполнена: "+root(error).getMessage()));else player.sendMessage(ClanService.color(ok?"&a"+success:"&cОперация отклонена."));}));}private static Throwable root(Throwable t){while(t.getCause()!=null)t=t.getCause();return t;}private static void deny(CommandSender s){s.sendMessage(ClanService.color("&cНедостаточно прав."));}private static void usage(CommandSender s){s.sendMessage("/clan create|invite|accept|info|leave|kick|promote|demote|ff|bank|disband");}
 @Override public @NotNull Collection<String> suggest(@NotNull CommandSourceStack source,@NotNull String[] args){if(args.length<=1)return List.of("create","invite","accept","info","leave","kick","promote","demote","ff","bank","disband","reload");if(args.length==2&&List.of("invite","kick","promote","demote").contains(args[0].toLowerCase(Locale.ROOT)))return Bukkit.getOnlinePlayers().stream().map(Player::getName).toList();if(args.length==2&&args[0].equalsIgnoreCase("ff"))return List.of("on","off");return List.of();}}
